## 五、极简代码示例（TypeScript）

用 OpenAI SDK + 内存数组模拟向量库，理解本质。真实项目把内存数组换成向量数据库即可。

```typescript
import OpenAI from "openai";
const openai = new OpenAI();

// ===== 1. 索引阶段：把文档切块 + 向量化 =====
const docs = [
  "公司请假制度：年假每年15天，需提前3天申请。",
  "报销流程：填报销单附发票，提交部门经理审批。",
  "上班时间：周一至周五 9:00-18:00，午休1小时。",
];

async function embed(text: string): Promise<number[]> {
  const res = await openai.embeddings.create({
    model: "text-embedding-3-small",
    input: text,
  });
  return res.data[0].embedding;
}

const docVectors = await Promise.all(docs.map(embed));

// ===== 2. 检索阶段：问题向量化 + 找最相似的 Top-2 =====
const question = "年假有几天？";
const qVector = await embed(question);

function cosineSim(a: number[], b: number[]) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] ** 2;
    nb += b[i] ** 2;
  }
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

const topK = docVectors
  .map((v, i) => ({ doc: docs[i], score: cosineSim(v, qVector) }))
  .sort((a, b) => b.score - a.score)
  .slice(0, 2);

// ===== 3. 生成阶段：把检索结果拼进 Prompt，让模型回答 =====
const context = topK.map((t) => t.doc).join("\n");

const reply = await openai.chat.completions.create({
  model: "gpt-4o-mini",
  messages: [
    {
      role: "system",
      content: `根据以下资料回答问题，资料中没有就说"不知道"。\n\n资料:\n${context}`,
    },
    { role: "user", content: question },
  ],
});

console.log(reply.choices[0].message.content);
// ✅ 输出：年假每年15天。
```

RAG 的本质就这么简单——检索 + 拼接 + 生成。后面所有进阶都是在优化这三个环节。

## 代码 `Code/test_langgraph_agent.py`

```python
import os
from typing import TypedDict, Annotated
from langgraph.graph import StateGraph, END
from langgraph.graph.message import add_messages
from langchain_openai import ChatOpenAI
from langchain_core.tools import tool
from langchain_core.messages import ToolMessage

# 1. 工具：@tool 装饰器自动生成 schema
@tool
def get_weather(city: str) -> str:
    """查询指定城市的天气"""
    fake = {"上海": "32度晴", "北京": "35度晴", "广州": "30度雷阵雨"}
    return fake.get(city, "未知")

@tool
def calculate(expression: str) -> str:
    """数学表达式计算，如 '3*4'"""
    try:
        return str(eval(expression, {"__builtins__": {}}, {}))
    except Exception as e:
        return f"计算失败: {e}"

TOOLS = [get_weather, calculate]
TOOL_BY_NAME = {t.name: t for t in TOOLS}

# 2. 模型 + 绑定工具
model = ChatOpenAI(
    model="glm-5.2",
    api_key=os.getenv("OPENAI_API_KEY"),
    base_url="https://ark.cn-beijing.volces.com/api/coding/v3",
).bind_tools(TOOLS)

# 3. State
class AgentState(TypedDict):
    messages: Annotated[list, add_messages]

# 4. 节点函数
def agent_node(state: AgentState):
    reply = model.invoke(state["messages"])
    return {"messages": [reply]}

def tools_node(state: AgentState):
    last = state["messages"][-1]
    results = []
    for tc in last.tool_calls:
        fn = TOOL_BY_NAME[tc["name"]]
        output = fn.invoke(tc["args"])
        results.append(ToolMessage(content=str(output), tool_call_id=tc["id"]))
    return {"messages": results}

def route_fn(state: AgentState) -> str:
    last = state["messages"][-1]
    if last.tool_calls:
        return "continue"
    return "end"

# 5. 拼图
graph = StateGraph(AgentState)
graph.add_node("agent", agent_node)
graph.add_node("tools", tools_node)
graph.add_edge("tools", "agent")
graph.add_conditional_edges("agent", route_fn, {"continue": "tools", "end": END})
graph.set_entry_point("agent")
app = graph.compile()

# 6. 跑
result = app.invoke({
    "messages": [{"role": "user", "content": "查上海和北京的天气，告诉我哪个更热"}]
})
for msg in result["messages"]:
    role = msg.__class__.__name__
    print(f"[{role}] {msg.content}")
    if hasattr(msg, "tool_calls") and msg.tool_calls:
        print(f"  -> tool_calls: {msg.tool_calls}")
```

